insert into commission_rules (id, name, rate_bps, destination_id, active) values ('e7354fe3-64cf-5826-90e5-403e5d85949d', 'Global default', 1500, null, true) on conflict (id) do nothing;
insert into destinations (id, slug, name, country, region, summary, description, image_url, featured) values ('8248a0e1-98ef-56ea-bb13-6c6487dab2d8', 'zanzibar', 'Zanzibar', 'Tanzania', 'Unguja', 'Turquoise water, spice farms and Swahili soul off the coast of East Africa.', 'An archipelago in the Indian Ocean where dhow sails still catch the wind and the reefs are close enough to swim to. Stone Town''s alleys open onto white-sand beaches; spice farms scent the inland air. Zanzibar is where Paradise Beyond began.', '/api/placeholder?seed=pb-zanzibar-beach&w=2000&h=1200', true) on conflict (id) do nothing;
insert into destinations (id, slug, name, country, region, summary, description, image_url, featured) values ('82a58d26-b338-50b2-9581-0c9938ad9efd', 'pemba', 'Pemba', 'Tanzania', 'Pemba Island', 'The greener, quieter sister island — steep reefs and near-empty coves.', 'Less travelled than Unguja, Pemba is hilly, green and ringed by some of the best wall-diving in the Indian Ocean. For those who want the archipelago at its most remote.', '/api/placeholder?seed=pb-pemba-green&w=2000&h=1200', false) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('28245f1d-1edb-5bfc-834a-b0d1be6a9939', 'wellness', 'Wellness', null, 'Yoga, meditation, detox, sound healing.', 'Slow mornings, salt air and practices that put you back together. Wellness experiences are built around rest, movement and stillness.', 0) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('c4eac551-5fd1-5a00-be0e-9d25c52115a6', 'adventure', 'Adventure', null, 'Diving, kitesurfing, sailing, hiking.', 'For the ones who''d rather be in the water than beside it. Adventure experiences move — reefs, wind, open ocean and long horizons.', 1) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('e4f19c15-60f3-504a-84a8-188724a9abf3', 'family', 'Family', null, 'Adventure weeks and nature for all ages.', 'Time together that everyone actually remembers. Family experiences balance wonder for children with real rest for parents.', 2) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('e668dcab-02ba-51a4-9d01-0e3cc6a63e12', 'food', 'Food', null, 'Cooking, spice, farm-to-table.', 'Zanzibar is the Spice Island. Food experiences take you from the farm and the market to the fire and the table.', 3) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('ce4393b9-be6f-55f1-a000-d4ae33bc6588', 'creative', 'Creative', null, 'Photography, writing, art and music.', 'Make something while the light is this good. Creative experiences pair craft with place, mentored by working artists.', 4) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('17c8ef91-510f-5634-9900-7ce6f187a05d', 'nature', 'Nature', null, 'Conservation, marine life and wildlife.', 'Get close to the living reef and the forest. Nature experiences are led by conservationists and marine scientists.', 5) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('68702c63-2c36-519a-bde4-2be809cea0fc', 'work', 'Work', 'Connection', 'Founder, team and remote-work retreats.', 'Take the team somewhere that changes the conversation. Work experiences blend focused sessions with genuine connection.', 6) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('6aa7df17-1c2a-53c4-92db-d551ef87a762', 'transformation', 'Transformation', null, 'Fitness, personal development, lifestyle.', 'Give yourself the fourteen days it actually takes. Transformation experiences are structured programmes with real outcomes.', 7) on conflict (id) do nothing;
insert into categories (id, slug, name, display_label, tagline, description, sort_order) values ('56d88935-6253-5d7e-babd-cf0221763f37', 'paradise-holidays', 'Paradise Holidays', null, 'Curated holidays, beautifully arranged.', 'Not every trip is a retreat. Paradise Holidays are curated journeys — accommodation, transfers and selected experiences, handled.', 8) on conflict (id) do nothing;
insert into hosts (id, owner_id, slug, name, headline, bio, qualifications, specialisms, socials, image_url, verified) values ('1e1e7491-5577-5156-9432-ea833e5ca960', null, 'amina-yusuf', 'Amina Yusuf', 'Yoga teacher & breathwork guide', 'Amina has taught yoga on the Zanzibari coast for over a decade. Her retreats are unhurried and deeply restorative — built for people who arrive exhausted and leave lighter. She trained in Mysore and Bali and teaches a warm, accessible vinyasa.', array['500hr Yoga Alliance', 'Advanced Breathwork Facilitator', 'Trauma-informed teaching']::text[], array['Restorative yoga', 'Breathwork', 'Burnout recovery']::text[], '[{"label":"Instagram","href":"#"},{"label":"Website","href":"#"}]'::jsonb, '/api/placeholder?seed=pb-host-amina&w=600&h=720', true) on conflict (id) do nothing;
insert into hosts (id, owner_id, slug, name, headline, bio, qualifications, specialisms, socials, image_url, verified) values ('5af45d6b-96e7-54ea-987a-e0012d22a2ba', null, 'marco-benali', 'Marco Benali', 'PADI instructor & marine guide', 'Marco runs a small dive centre on the north coast and has logged thousands of dives across the Pemba channel. He''s happiest introducing first-timers to the reef and pointing experienced divers toward the walls few people ever see.', array['PADI Master Scuba Diver Trainer', 'Emergency First Response Instructor', 'Marine ID specialist']::text[], array['Reef diving', 'Wall diving', 'Freediving']::text[], '[{"label":"Instagram","href":"#"}]'::jsonb, '/api/placeholder?seed=pb-host-marco&w=600&h=720', true) on conflict (id) do nothing;
insert into hosts (id, owner_id, slug, name, headline, bio, qualifications, specialisms, socials, image_url, verified) values ('b327f066-1679-503a-a5da-23cfddf75229', null, 'fatma-said', 'Fatma Said', 'Chef & spice-farm host', 'Fatma grew up between a Stone Town kitchen and her family''s spice farm. Her food experiences move from market to farm to table, teaching the Swahili, Indian and Omani threads that make Zanzibari cooking what it is.', array['Trained at a Stone Town culinary school', 'Farm-to-table practitioner']::text[], array['Swahili cuisine', 'Spice growing', 'Market cooking']::text[], '[{"label":"Instagram","href":"#"},{"label":"Website","href":"#"}]'::jsonb, '/api/placeholder?seed=pb-host-fatma&w=600&h=720', true) on conflict (id) do nothing;
insert into hosts (id, owner_id, slug, name, headline, bio, qualifications, specialisms, socials, image_url, verified) values ('0b3960ff-fb7a-5846-bd32-539d6f195061', null, 'james-okoth', 'James Okoth', 'Photographer & mentor', 'A working travel and documentary photographer, James leads small creative groups along the coast and through Stone Town, teaching people to see light and make photographs they''re proud of.', array['15 years working photographer', 'Published in international press']::text[], array['Travel photography', 'Portraiture', 'Editing']::text[], '[{"label":"Instagram","href":"#"},{"label":"Portfolio","href":"#"}]'::jsonb, '/api/placeholder?seed=pb-host-james&w=600&h=720', true) on conflict (id) do nothing;
insert into hosts (id, owner_id, slug, name, headline, bio, qualifications, specialisms, socials, image_url, verified) values ('df3b36a5-c145-55ff-adff-bfb60261cd69', null, 'sofia-mbwana', 'Sofia Mbwana', 'Marine biologist & conservationist', 'Sofia works with a coral-restoration project on the archipelago. Her nature experiences put guests to work — surveying reefs, planting coral and understanding an ocean under pressure.', array['MSc Marine Biology', 'Reef survey lead', 'Dive rescue certified']::text[], array['Coral restoration', 'Reef ecology', 'Citizen science']::text[], '[{"label":"Website","href":"#"}]'::jsonb, '/api/placeholder?seed=pb-host-sofia&w=600&h=720', true) on conflict (id) do nothing;
insert into hosts (id, owner_id, slug, name, headline, bio, qualifications, specialisms, socials, image_url, verified) values ('961695fe-9764-59b2-80d2-ec9e047d8fc3', null, 'daniel-hart', 'Daniel Hart', 'Performance coach & founder retreat host', 'A former operator turned coach, Daniel runs focused retreats for founders and small teams — half deep-work and strategy, half the kind of connection that only happens away from the office.', array['Executive coaching accreditation', 'Ex-founder']::text[], array['Founder retreats', 'Team offsites', 'Deep work']::text[], '[{"label":"LinkedIn","href":"#"},{"label":"Website","href":"#"}]'::jsonb, '/api/placeholder?seed=pb-host-daniel&w=600&h=720', false) on conflict (id) do nothing;
insert into properties (id, destination_id, name, description, location_label, verified) values ('7cd8989f-6720-500d-914d-f339eb16c2f4', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', 'Kendwa Beach House', 'A small, barefoot-luxury beach house steps from the sand. Whitewashed rooms, sea breezes, and a shaded yoga deck facing the water.', 'Kendwa, Zanzibar', true) on conflict (id) do nothing;
insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('83e5dee9-2997-5ec1-962a-4221b3f9b621', 'zanzibar-reconnection', 'Zanzibar Reconnection', 'Seven days to come back to yourself on the north coast.', 'published', '7', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', '7cd8989f-6720-500d-914d-f339eb16c2f4', 'Kendwa, Zanzibar', 'USD', 165000, 12, true, true, '/api/placeholder?seed=pb-reconnection-hero&w=2000&h=1200', '["Reconnection is a week built around one idea: that rest is not a reward you earn, but a place you return to. Mornings begin slowly, with tea on the sand before the day warms.","Amina''s teaching is gentle and unhurried — vinyasa that meets you where you are, breathwork that quietly resets your nervous system, and long afternoons with nothing you have to do. Evenings are shared, over food, as the sky turns.","You''ll leave with the thing you actually came for: a slower pulse, and the memory of how it feels to be unhurried."]'::jsonb, '["You''ve been running on empty and know it.","You want yoga and rest without dogma or pressure.","You''d like to arrive as a stranger and leave with a small, warm group of friends."]'::jsonb, '{"slug":"zanzibar-reconnection","name":"Zanzibar Reconnection","strapline":"Seven days to come back to yourself on the north coast.","duration":7,"destinationSlug":"zanzibar","location":"Kendwa, Zanzibar","categorySlugs":["wellness"],"hostSlugs":["amina-yusuf"],"verified":true,"currency":"USD","priceFromMinor":165000,"maxGroupSize":12,"heroImageSeed":"reconnection-hero","gallerySeeds":["reconnection-1","reconnection-2","reconnection-3","reconnection-4"],"forYouIf":["You''ve been running on empty and know it.","You want yoga and rest without dogma or pressure.","You''d like to arrive as a stranger and leave with a small, warm group of friends."],"story":["Reconnection is a week built around one idea: that rest is not a reward you earn, but a place you return to. Mornings begin slowly, with tea on the sand before the day warms.","Amina''s teaching is gentle and unhurried — vinyasa that meets you where you are, breathwork that quietly resets your nervous system, and long afternoons with nothing you have to do. Evenings are shared, over food, as the sky turns.","You''ll leave with the thing you actually came for: a slower pulse, and the memory of how it feels to be unhurried."],"highlights":[{"title":"Daily beachfront yoga","description":"Two unhurried practices a day, sunrise and late afternoon.","imageSeed":"recon-yoga"},{"title":"Breathwork & sound","description":"Guided breathwork and a closing sound-healing session.","imageSeed":"recon-sound"},{"title":"Dhow sunset sail","description":"An evening on the water aboard a traditional dhow.","imageSeed":"recon-dhow"},{"title":"Two massages","description":"Two full-body massages built into the week.","imageSeed":"recon-massage"}],"stay":{"property":"Kendwa Beach House","description":"A small, barefoot-luxury beach house steps from the sand. Whitewashed rooms, sea breezes, and a shaded yoga deck facing the water.","roomTypes":[{"id":"shared-twin","name":"Shared Twin","description":"A room shared with one other guest, twin beds.","occupancy":"shared","priceDeltaMinor":0},{"id":"private-garden","name":"Private Garden Room","description":"Your own room facing the garden.","occupancy":"private","priceDeltaMinor":35000},{"id":"private-sea","name":"Private Sea-View Room","description":"Private room with a sea view and balcony.","occupancy":"private","priceDeltaMinor":60000}],"imageSeeds":["recon-room-1","recon-room-2","recon-room-3"]},"inclusions":["7 nights accommodation","Breakfast and dinner daily","Two daily yoga sessions","Breathwork and sound-healing sessions","Two full-body massages","Sunset dhow sail","Zanzibar airport transfers","All scheduled activities"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Arrive","summary":"Airport pickup and a soft landing.","items":[{"title":"Airport pickup"},{"title":"Welcome drink"},{"title":"Settle in"},{"title":"Sunset dinner on the beach"}]},{"day":2,"title":"Reset","summary":"Find the rhythm of the week.","items":[{"title":"Morning yoga"},{"title":"Breakfast"},{"title":"Beach time"},{"title":"Massage"},{"title":"Group dinner"}]},{"day":3,"title":"Breathe","summary":"Down into the nervous system.","items":[{"title":"Morning yoga"},{"title":"Breathwork session"},{"title":"Free afternoon"},{"title":"Evening restorative practice"}]},{"day":4,"title":"Drift","summary":"A day on the water.","items":[{"title":"Morning yoga"},{"title":"Snorkelling trip"},{"title":"Lunch aboard"},{"title":"Rest"},{"title":"Dinner"}]},{"day":5,"title":"Open","summary":"Space to do very little.","items":[{"title":"Morning yoga"},{"title":"Free day"},{"title":"Optional massage"},{"title":"Sunset dhow sail"}]},{"day":6,"title":"Deepen","summary":"The quiet centre of the week.","items":[{"title":"Morning yoga"},{"title":"Breathwork"},{"title":"Beach time"},{"title":"Sound-healing session"},{"title":"Group dinner"}]},{"day":7,"title":"Return","summary":"Carry it home.","items":[{"title":"Closing practice"},{"title":"Breakfast"},{"title":"Airport transfer"}]}],"departures":[{"id":"zr-2026-10","startDate":"2026-10-12","endDate":"2026-10-18","priceFromMinor":165000,"currency":"USD","capacity":12,"spacesRemaining":4,"depositMinor":45000,"balanceDueDays":45,"status":"open"},{"id":"zr-2026-11","startDate":"2026-11-09","endDate":"2026-11-15","priceFromMinor":165000,"currency":"USD","capacity":12,"spacesRemaining":9,"depositMinor":45000,"balanceDueDays":45,"status":"open"},{"id":"zr-2026-12","startDate":"2026-12-07","endDate":"2026-12-13","priceFromMinor":178000,"currency":"USD","capacity":12,"spacesRemaining":12,"depositMinor":45000,"balanceDueDays":45,"status":"open"}],"featured":true}'::jsonb) on conflict (id) do nothing;
