insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('9f9a30d5-b45c-5587-8b39-9a4a5c55c1a2', 'deep-blue-immersion', 'Deep Blue Immersion', 'Learn to dive, or go deeper, on the reefs of the north.', 'published', '7', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', '05370880-58cb-557a-847a-84cd1a2636bb', 'Nungwi, Zanzibar', 'USD', 189000, 8, true, true, '/api/placeholder?seed=pb-deepblue-hero&w=2000&h=1200', '["A week for people who''d rather be under the water than beside it. Whether you''ve never breathed from a regulator or you''ve a hundred dives logged, Marco builds the week around where you are.","Beginners earn their open-water certification over the week. Certified divers head further out — to the channel walls, the drift sites and the reefs most visitors never reach. Evenings are for salt-tired dinners and the day''s sightings."]'::jsonb, '["You''ve always meant to learn to dive.","You''re already certified and want walls, drift and turtles.","You want your days measured in dives, not hours."]'::jsonb, '{"slug":"deep-blue-immersion","name":"Deep Blue Immersion","strapline":"Learn to dive, or go deeper, on the reefs of the north.","duration":7,"destinationSlug":"zanzibar","location":"Nungwi, Zanzibar","categorySlugs":["adventure","nature"],"hostSlugs":["marco-benali"],"verified":true,"currency":"USD","priceFromMinor":189000,"maxGroupSize":8,"heroImageSeed":"deepblue-hero","gallerySeeds":["deepblue-1","deepblue-2","deepblue-3","deepblue-4"],"forYouIf":["You''ve always meant to learn to dive.","You''re already certified and want walls, drift and turtles.","You want your days measured in dives, not hours."],"story":["A week for people who''d rather be under the water than beside it. Whether you''ve never breathed from a regulator or you''ve a hundred dives logged, Marco builds the week around where you are.","Beginners earn their open-water certification over the week. Certified divers head further out — to the channel walls, the drift sites and the reefs most visitors never reach. Evenings are for salt-tired dinners and the day''s sightings."],"highlights":[{"title":"Guided reef dives","description":"Daily dives on the north-coast reefs, guided throughout.","imageSeed":"db-reef"},{"title":"Certification track","description":"Beginners complete an open-water course with Marco.","imageSeed":"db-cert"},{"title":"Turtle & wall sites","description":"Access to walls and drift sites for certified divers.","imageSeed":"db-turtle"},{"title":"Freedive session","description":"An introduction to breath-hold freediving.","imageSeed":"db-free"}],"stay":{"property":"Nungwi Dive Lodge","description":"A relaxed divers'' lodge a two-minute walk from the dive centre, with a pool to practise skills and a deck over the water.","roomTypes":[{"id":"shared-bunk","name":"Shared Room","description":"A twin room shared with a fellow diver.","occupancy":"shared","priceDeltaMinor":0},{"id":"private","name":"Private Room","description":"Your own room with sea breeze.","occupancy":"private","priceDeltaMinor":42000}],"imageSeeds":["db-room-1","db-room-2"]},"inclusions":["7 nights accommodation","Breakfast daily","Up to 10 guided dives (level depending)","All dive equipment","Open-water certification for beginners","Freediving intro session","Airport transfers"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Arrive","summary":"Land and gear up.","items":[{"title":"Airport pickup"},{"title":"Equipment fitting"},{"title":"Welcome dinner"}]},{"day":2,"title":"First breaths","summary":"Into the water.","items":[{"title":"Theory & pool session"},{"title":"First open-water dive"},{"title":"Debrief"}]},{"day":3,"title":"Descend","summary":"Two dives.","items":[{"title":"Two guided dives"},{"title":"Surface interval lunch"},{"title":"Log & rest"}]},{"day":4,"title":"The reef","summary":"Longer bottom times.","items":[{"title":"Two reef dives"},{"title":"Marine ID session"},{"title":"Beach evening"}]},{"day":5,"title":"The wall","summary":"Deeper water.","items":[{"title":"Wall / drift dive"},{"title":"Free afternoon"},{"title":"Group dinner"}]},{"day":6,"title":"Freedive","summary":"On a single breath.","items":[{"title":"Freediving session"},{"title":"Final fun dive"},{"title":"Sunset"}]},{"day":7,"title":"Surface","summary":"Home with salt in your hair.","items":[{"title":"Breakfast"},{"title":"Airport transfer"}]}],"departures":[{"id":"db-2026-09","startDate":"2026-09-21","endDate":"2026-09-27","priceFromMinor":189000,"currency":"USD","capacity":8,"spacesRemaining":2,"depositMinor":55000,"balanceDueDays":45,"status":"open"},{"id":"db-2026-10","startDate":"2026-10-19","endDate":"2026-10-25","priceFromMinor":189000,"currency":"USD","capacity":8,"spacesRemaining":6,"depositMinor":55000,"balanceDueDays":45,"status":"open"},{"id":"db-2027-01","startDate":"2027-01-18","endDate":"2027-01-24","priceFromMinor":199000,"currency":"USD","capacity":8,"spacesRemaining":8,"depositMinor":55000,"balanceDueDays":45,"status":"open"}],"featured":true}'::jsonb) on conflict (id) do nothing;
