insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('1ea42738-d0d2-5cd6-9627-fe08b72681ba', 'spice-fire-and-table', 'Spice, Fire & Table', 'A week eating and cooking your way across the Spice Island.', 'published', '7', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', 'f126eac7-abe6-5b27-9a30-fb08c504dc59', 'Stone Town, Zanzibar', 'USD', 152000, 10, true, false, '/api/placeholder?seed=pb-spice-hero&w=2000&h=1200', '["Zanzibar earned its name from spice, and Fatma''s week follows that thread from soil to plate. You''ll shop the Darajani market at dawn, grind your own masala, and learn the dishes that define the coast.","Days move between Stone Town''s kitchens, a working spice farm and long shared tables. By the end you''ll cook a Swahili meal from memory — and understand the history in every dish."]'::jsonb, '["You travel for the food first.","You want to actually cook, not just watch.","You''re curious about where Swahili, Indian and Omani kitchens meet."]'::jsonb, '{"slug":"spice-fire-and-table","name":"Spice, Fire & Table","strapline":"A week eating and cooking your way across the Spice Island.","duration":7,"destinationSlug":"zanzibar","location":"Stone Town, Zanzibar","categorySlugs":["food"],"hostSlugs":["fatma-said"],"verified":true,"currency":"USD","priceFromMinor":152000,"maxGroupSize":10,"heroImageSeed":"spice-hero","gallerySeeds":["spice-1","spice-2","spice-3","spice-4"],"forYouIf":["You travel for the food first.","You want to actually cook, not just watch.","You''re curious about where Swahili, Indian and Omani kitchens meet."],"story":["Zanzibar earned its name from spice, and Fatma''s week follows that thread from soil to plate. You''ll shop the Darajani market at dawn, grind your own masala, and learn the dishes that define the coast.","Days move between Stone Town''s kitchens, a working spice farm and long shared tables. By the end you''ll cook a Swahili meal from memory — and understand the history in every dish."],"highlights":[{"title":"Darajani market","description":"A dawn tour of Stone Town''s great market with Fatma.","imageSeed":"spice-market"},{"title":"Spice farm day","description":"Harvest and cook at a working spice farm.","imageSeed":"spice-farm"},{"title":"Hands-on classes","description":"Daily cooking classes, from biryani to urojo.","imageSeed":"spice-cook"},{"title":"Fishermen''s catch","description":"Cook the day''s catch straight off the boats.","imageSeed":"spice-fish"}],"stay":{"property":"Stone Town Merchant House","description":"A restored Swahili merchant''s house in the heart of Stone Town, with carved doors, a rooftop terrace and a courtyard kitchen.","roomTypes":[{"id":"shared","name":"Shared Room","description":"A characterful twin room shared with one guest.","occupancy":"shared","priceDeltaMinor":0},{"id":"private","name":"Private Room","description":"A private heritage room with courtyard views.","occupancy":"private","priceDeltaMinor":38000}],"imageSeeds":["spice-room-1","spice-room-2"]},"inclusions":["7 nights accommodation","All breakfasts and most meals (you cook them)","Daily cooking classes","Darajani market tour","Full spice-farm day","Recipe collection to take home","Airport transfers"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Arrive","summary":"Into the old town.","items":[{"title":"Airport pickup"},{"title":"Rooftop welcome dinner"}]},{"day":2,"title":"Market","summary":"Where it all starts.","items":[{"title":"Dawn market tour"},{"title":"First cooking class"},{"title":"Shared lunch"},{"title":"Free evening"}]},{"day":3,"title":"Spice farm","summary":"Soil to spice.","items":[{"title":"Spice-farm day"},{"title":"Farm lunch"},{"title":"Evening at leisure"}]},{"day":4,"title":"The sea","summary":"Off the boats.","items":[{"title":"Fish-market visit"},{"title":"Seafood cookery class"},{"title":"Sunset"}]},{"day":5,"title":"Sweet & street","summary":"The city''s flavours.","items":[{"title":"Street-food walk"},{"title":"Zanzibari sweets class"},{"title":"Forodhani night market"}]},{"day":6,"title":"Feast","summary":"Cook the big meal.","items":[{"title":"Full Swahili feast prep"},{"title":"Guest table dinner"}]},{"day":7,"title":"Depart","summary":"Full and inspired.","items":[{"title":"Breakfast"},{"title":"Airport transfer"}]}],"departures":[{"id":"sf-2026-09","startDate":"2026-09-14","endDate":"2026-09-20","priceFromMinor":152000,"currency":"USD","capacity":10,"spacesRemaining":3,"depositMinor":40000,"balanceDueDays":45,"status":"open"},{"id":"sf-2026-11","startDate":"2026-11-16","endDate":"2026-11-22","priceFromMinor":152000,"currency":"USD","capacity":10,"spacesRemaining":7,"depositMinor":40000,"balanceDueDays":45,"status":"open"}],"featured":false}'::jsonb) on conflict (id) do nothing;
