insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('1d082bec-147c-5848-b832-ed0b40adc684', 'the-long-exhale', 'The Long Exhale', 'Fourteen days to properly disappear and come back different.', 'published', '14', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', '8d603169-be6e-539f-bd43-d7924a50dfc0', 'Paje, Zanzibar', 'USD', 298000, 10, true, true, '/api/placeholder?seed=pb-exhale-hero&w=2000&h=1200', '["Some things take longer than seven days. The Long Exhale is a fortnight designed in two arcs: the first week to let go, the second to rebuild. Yoga and breathwork run throughout, but the real work is the space between.","By the second week the noise has gone quiet enough to hear yourself think. Amina holds the whole arc — practice, rest, one-to-one time and the slow return. People come back from this one changed."]'::jsonb, '["A week isn''t enough and you know it.","You want real change, not just a rest.","You''re ready to give yourself two proper weeks."]'::jsonb, '{"slug":"the-long-exhale","name":"The Long Exhale","strapline":"Fourteen days to properly disappear and come back different.","duration":14,"destinationSlug":"zanzibar","location":"Paje, Zanzibar","categorySlugs":["wellness","transformation"],"hostSlugs":["amina-yusuf"],"verified":true,"currency":"USD","priceFromMinor":298000,"maxGroupSize":10,"heroImageSeed":"exhale-hero","gallerySeeds":["exhale-1","exhale-2","exhale-3","exhale-4"],"forYouIf":["A week isn''t enough and you know it.","You want real change, not just a rest.","You''re ready to give yourself two proper weeks."],"story":["Some things take longer than seven days. The Long Exhale is a fortnight designed in two arcs: the first week to let go, the second to rebuild. Yoga and breathwork run throughout, but the real work is the space between.","By the second week the noise has gone quiet enough to hear yourself think. Amina holds the whole arc — practice, rest, one-to-one time and the slow return. People come back from this one changed."],"highlights":[{"title":"Two-week arc","description":"A structured fortnight: release, then rebuild.","imageSeed":"ex-arc"},{"title":"1:1 sessions","description":"Private sessions with Amina through the fortnight.","imageSeed":"ex-solo"},{"title":"Digital sunset","description":"An optional phone-light second week.","imageSeed":"ex-digital"},{"title":"Island day trips","description":"Sandbank picnics and a Jozani forest walk.","imageSeed":"ex-trip"}],"stay":{"property":"Paje Lagoon Retreat","description":"A serene retreat on the calm Paje lagoon, with a large shala, hammocks in the palms and rooms opening to the sea breeze.","roomTypes":[{"id":"shared","name":"Shared Room","description":"Twin room shared with one guest.","occupancy":"shared","priceDeltaMinor":0},{"id":"private","name":"Private Room","description":"Private room, garden facing.","occupancy":"private","priceDeltaMinor":62000},{"id":"private-sea","name":"Private Sea-View","description":"Private room facing the lagoon.","occupancy":"private","priceDeltaMinor":98000}],"imageSeeds":["ex-room-1","ex-room-2","ex-room-3"]},"inclusions":["14 nights accommodation","Breakfast and dinner daily","Two daily yoga sessions","Weekly private session with Amina","Breathwork and meditation programme","Three massages","Sandbank picnic and Jozani forest trip","Airport transfers"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Arrive","summary":"Begin the long exhale.","items":[{"title":"Airport pickup"},{"title":"Welcome circle"},{"title":"Dinner"}]},{"day":2,"title":"Land","summary":"Settle the body.","items":[{"title":"Morning yoga"},{"title":"Restorative afternoon"},{"title":"Massage"}]},{"day":3,"title":"Release","summary":"Let the week go.","items":[{"title":"Yoga"},{"title":"Breathwork"},{"title":"Beach time"}]},{"day":4,"title":"Quiet","summary":"Less, on purpose.","items":[{"title":"Yoga"},{"title":"Free day"},{"title":"Evening meditation"}]},{"day":5,"title":"Water","summary":"Out to the sandbank.","items":[{"title":"Yoga"},{"title":"Sandbank picnic"},{"title":"Rest"}]},{"day":6,"title":"Root","summary":"First 1:1.","items":[{"title":"Yoga"},{"title":"Private session"},{"title":"Group dinner"}]},{"day":7,"title":"Pause","summary":"Halfway.","items":[{"title":"Gentle practice"},{"title":"Rest day"},{"title":"Sunset"}]},{"day":8,"title":"Turn","summary":"Begin to rebuild.","items":[{"title":"Yoga"},{"title":"Intention setting"},{"title":"Breathwork"}]},{"day":9,"title":"Move","summary":"Energy returns.","items":[{"title":"Stronger practice"},{"title":"Jozani forest walk"},{"title":"Dinner"}]},{"day":10,"title":"Steady","summary":"Find the new rhythm.","items":[{"title":"Yoga"},{"title":"Massage"},{"title":"Free afternoon"}]},{"day":11,"title":"Clear","summary":"Space to think.","items":[{"title":"Yoga"},{"title":"Second 1:1"},{"title":"Beach evening"}]},{"day":12,"title":"Build","summary":"Habits for home.","items":[{"title":"Yoga"},{"title":"Workshop"},{"title":"Group dinner"}]},{"day":13,"title":"Integrate","summary":"Carry it forward.","items":[{"title":"Yoga"},{"title":"Closing sound bath"},{"title":"Farewell dinner"}]},{"day":14,"title":"Return","summary":"Changed.","items":[{"title":"Closing circle"},{"title":"Airport transfer"}]}],"departures":[{"id":"le-2026-10","startDate":"2026-10-04","endDate":"2026-10-17","priceFromMinor":298000,"currency":"USD","capacity":10,"spacesRemaining":5,"depositMinor":90000,"balanceDueDays":45,"status":"open"},{"id":"le-2027-02","startDate":"2027-02-07","endDate":"2027-02-20","priceFromMinor":312000,"currency":"USD","capacity":10,"spacesRemaining":10,"depositMinor":90000,"balanceDueDays":45,"status":"open"}],"featured":true}'::jsonb) on conflict (id) do nothing;
