insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('4b6b6d21-6022-5e46-a8cc-4421a40d9554', 'island-light', 'Island Light', 'A photography week chasing the archipelago''s extraordinary light.', 'published', '7', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', '6e9c29ab-112b-5233-bfa8-5a06723ebc71', 'Stone Town & north coast, Zanzibar', 'USD', 172000, 8, true, false, '/api/placeholder?seed=pb-light-hero&w=2000&h=1200', '["Zanzibar is a photographer''s island — carved doors and dust-gold light in Stone Town, dhows on turquoise water, faces full of story. James leads a small group through it, teaching you to see and to make images that hold up.","Mornings and golden hours are for shooting; middays are for editing and honest, generous feedback. You''ll leave with a finished set and a real jump in your eye."]'::jsonb, '["You want to come home with photographs you''re proud of.","You''ve got a camera (or a phone) and want to truly use it.","You learn best by doing, in a small group."]'::jsonb, '{"slug":"island-light","name":"Island Light","strapline":"A photography week chasing the archipelago''s extraordinary light.","duration":7,"destinationSlug":"zanzibar","location":"Stone Town & north coast, Zanzibar","categorySlugs":["creative"],"hostSlugs":["james-okoth"],"verified":true,"currency":"USD","priceFromMinor":172000,"maxGroupSize":8,"heroImageSeed":"light-hero","gallerySeeds":["light-1","light-2","light-3","light-4"],"forYouIf":["You want to come home with photographs you''re proud of.","You''ve got a camera (or a phone) and want to truly use it.","You learn best by doing, in a small group."],"story":["Zanzibar is a photographer''s island — carved doors and dust-gold light in Stone Town, dhows on turquoise water, faces full of story. James leads a small group through it, teaching you to see and to make images that hold up.","Mornings and golden hours are for shooting; middays are for editing and honest, generous feedback. You''ll leave with a finished set and a real jump in your eye."],"highlights":[{"title":"Golden-hour shoots","description":"Daily sunrise and sunset shoots in the best light.","imageSeed":"lt-golden"},{"title":"Stone Town streets","description":"Guided street and portrait photography in the old town.","imageSeed":"lt-street"},{"title":"Editing sessions","description":"Hands-on editing and critique with James.","imageSeed":"lt-edit"},{"title":"Dhow & reef","description":"Shoot from a dhow on the open water.","imageSeed":"lt-dhow"}],"stay":{"property":"Stone Town Merchant House & North Coast Lodge","description":"Split between a heritage house in Stone Town and a north-coast lodge, so you shoot both the city and the sea.","roomTypes":[{"id":"shared","name":"Shared Room","description":"Twin room shared with a fellow photographer.","occupancy":"shared","priceDeltaMinor":0},{"id":"private","name":"Private Room","description":"Your own room in both locations.","occupancy":"private","priceDeltaMinor":44000}],"imageSeeds":["lt-room-1","lt-room-2"]},"inclusions":["7 nights accommodation (two locations)","Breakfast daily","Daily guided shoots","Editing and critique sessions","Dhow photography trip","Inter-location transfers","Airport transfers"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Arrive","summary":"Meet and calibrate.","items":[{"title":"Airport pickup"},{"title":"Welcome dinner"},{"title":"Gear check"}]},{"day":2,"title":"The old town","summary":"Learn to see.","items":[{"title":"Sunrise shoot"},{"title":"Street session"},{"title":"Editing"},{"title":"Golden-hour shoot"}]},{"day":3,"title":"Portraits","summary":"People and light.","items":[{"title":"Portrait workshop"},{"title":"Market shoot"},{"title":"Critique"}]},{"day":4,"title":"To the coast","summary":"Change of light.","items":[{"title":"Transfer north"},{"title":"Beach golden hour"},{"title":"Edit"}]},{"day":5,"title":"On the water","summary":"Blue and gold.","items":[{"title":"Dhow shoot"},{"title":"Reef & sail"},{"title":"Sunset"}]},{"day":6,"title":"Your project","summary":"Make your set.","items":[{"title":"Personal project shoot"},{"title":"Final edit"},{"title":"Slideshow dinner"}]},{"day":7,"title":"Depart","summary":"Portfolio in hand.","items":[{"title":"Breakfast"},{"title":"Airport transfer"}]}],"departures":[{"id":"il-2026-10","startDate":"2026-10-26","endDate":"2026-11-01","priceFromMinor":172000,"currency":"USD","capacity":8,"spacesRemaining":5,"depositMinor":50000,"balanceDueDays":45,"status":"open"},{"id":"il-2026-12","startDate":"2026-12-14","endDate":"2026-12-20","priceFromMinor":172000,"currency":"USD","capacity":8,"spacesRemaining":8,"depositMinor":50000,"balanceDueDays":45,"status":"open"}],"featured":false}'::jsonb) on conflict (id) do nothing;
