insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('da4a504d-3641-5637-9ea1-47c1f88d5e29', 'reef-guardians', 'Reef Guardians', 'Dive with purpose — a week restoring Pemba''s coral.', 'published', '7', '82a58d26-b338-50b2-9581-0c9938ad9efd', '45bb84f6-c8f6-5011-b54a-e6ec0d410096', 'Pemba Island, Tanzania', 'USD', 214000, 8, true, false, '/api/placeholder?seed=pb-reef-hero&w=2000&h=1200', '["Pemba''s reefs are among the healthiest in the region — and among the most worth protecting. This week puts you alongside marine biologist Sofia''s coral-restoration team: surveying reefs, tending coral nurseries and learning to read an ocean under pressure.","It''s a working week, not a spectator''s one. You''ll dive or snorkel every day, contribute real data, and leave understanding exactly what''s at stake and what''s being done about it."]'::jsonb, '["You want your holiday to leave something behind.","You care about the ocean and want to understand it.","You''re a comfortable swimmer (diving experience welcome, not required)."]'::jsonb, '{"slug":"reef-guardians","name":"Reef Guardians","strapline":"Dive with purpose — a week restoring Pemba''s coral.","duration":7,"destinationSlug":"pemba","location":"Pemba Island, Tanzania","categorySlugs":["nature","adventure"],"hostSlugs":["sofia-mbwana","marco-benali"],"verified":true,"currency":"USD","priceFromMinor":214000,"maxGroupSize":8,"heroImageSeed":"reef-hero","gallerySeeds":["reef-1","reef-2","reef-3","reef-4"],"forYouIf":["You want your holiday to leave something behind.","You care about the ocean and want to understand it.","You''re a comfortable swimmer (diving experience welcome, not required)."],"story":["Pemba''s reefs are among the healthiest in the region — and among the most worth protecting. This week puts you alongside marine biologist Sofia''s coral-restoration team: surveying reefs, tending coral nurseries and learning to read an ocean under pressure.","It''s a working week, not a spectator''s one. You''ll dive or snorkel every day, contribute real data, and leave understanding exactly what''s at stake and what''s being done about it."],"highlights":[{"title":"Coral nursery work","description":"Hands-on coral propagation and out-planting.","imageSeed":"rf-coral"},{"title":"Reef surveys","description":"Contribute to real reef-monitoring datasets.","imageSeed":"rf-survey"},{"title":"Wall diving","description":"Pemba''s famous drop-offs for certified divers.","imageSeed":"rf-wall"},{"title":"Science evenings","description":"Talks on reef ecology and conservation.","imageSeed":"rf-science"}],"stay":{"property":"Pemba Eco Lodge","description":"A low-impact eco lodge on a quiet Pemba cove, solar-powered, with the reef a short boat ride away.","roomTypes":[{"id":"shared","name":"Shared Banda","description":"A shared thatched banda, twin beds.","occupancy":"shared","priceDeltaMinor":0},{"id":"private","name":"Private Banda","description":"Your own banda overlooking the cove.","occupancy":"private","priceDeltaMinor":48000}],"imageSeeds":["rf-room-1","rf-room-2"]},"inclusions":["7 nights accommodation","All meals","Daily dives or snorkelling","Conservation training and materials","Reef-survey certification","Boat transfers to sites","Pemba airport transfers"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Arrive","summary":"To the quiet island.","items":[{"title":"Pemba pickup"},{"title":"Orientation"},{"title":"Welcome dinner"}]},{"day":2,"title":"Learn the reef","summary":"Ecology first.","items":[{"title":"Reef ecology session"},{"title":"First survey dive"},{"title":"Debrief"}]},{"day":3,"title":"The nursery","summary":"Grow coral.","items":[{"title":"Coral nursery work"},{"title":"Afternoon dive"},{"title":"Science talk"}]},{"day":4,"title":"Survey","summary":"Collect the data.","items":[{"title":"Two survey dives"},{"title":"Data logging"},{"title":"Beach evening"}]},{"day":5,"title":"The wall","summary":"Pemba''s drop-offs.","items":[{"title":"Wall dive / deep snorkel"},{"title":"Free afternoon"},{"title":"Dinner"}]},{"day":6,"title":"Out-plant","summary":"Give back.","items":[{"title":"Coral out-planting"},{"title":"Final dive"},{"title":"Celebration dinner"}]},{"day":7,"title":"Depart","summary":"Leave it better.","items":[{"title":"Breakfast"},{"title":"Airport transfer"}]}],"departures":[{"id":"rg-2026-09","startDate":"2026-09-28","endDate":"2026-10-04","priceFromMinor":214000,"currency":"USD","capacity":8,"spacesRemaining":4,"depositMinor":60000,"balanceDueDays":45,"status":"open"},{"id":"rg-2027-02","startDate":"2027-02-15","endDate":"2027-02-21","priceFromMinor":214000,"currency":"USD","capacity":8,"spacesRemaining":8,"depositMinor":60000,"balanceDueDays":45,"status":"open"}],"featured":false}'::jsonb) on conflict (id) do nothing;
