insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('1f37b46f-dcf4-51d3-b624-f412d3863bea', 'founders-offshore', 'Founders Offshore', 'A week that resets how your team thinks and works.', 'published', '7', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', 'd4ce7b20-8be8-59b8-9941-357010406055', 'Michamvi, Zanzibar', 'USD', 245000, 14, false, false, '/api/placeholder?seed=pb-founders-hero&w=2000&h=1200', '["The best strategy rarely comes in a boardroom. Founders Offshore takes small teams to a quiet peninsula for a week of deep work in the mornings and genuine connection the rest of the time.","Daniel structures the week around your goals — planning, positioning, hard conversations — with reef swims, sunset sails and long dinners doing the quiet work of turning colleagues back into a team."]'::jsonb, '["You''re a founder or lead who needs to think, not just do.","You want a team offsite that isn''t a hotel conference room.","You believe the best connection happens away from the office."]'::jsonb, '{"slug":"founders-offshore","name":"Founders Offshore","strapline":"A week that resets how your team thinks and works.","duration":7,"destinationSlug":"zanzibar","location":"Michamvi, Zanzibar","categorySlugs":["work"],"hostSlugs":["daniel-hart"],"verified":false,"currency":"USD","priceFromMinor":245000,"maxGroupSize":14,"heroImageSeed":"founders-hero","gallerySeeds":["founders-1","founders-2","founders-3","founders-4"],"forYouIf":["You''re a founder or lead who needs to think, not just do.","You want a team offsite that isn''t a hotel conference room.","You believe the best connection happens away from the office."],"story":["The best strategy rarely comes in a boardroom. Founders Offshore takes small teams to a quiet peninsula for a week of deep work in the mornings and genuine connection the rest of the time.","Daniel structures the week around your goals — planning, positioning, hard conversations — with reef swims, sunset sails and long dinners doing the quiet work of turning colleagues back into a team."],"highlights":[{"title":"Facilitated sessions","description":"Structured strategy and planning, led by Daniel.","imageSeed":"fo-session"},{"title":"Deep-work mornings","description":"Protected focus time with fast wifi and no noise.","imageSeed":"fo-focus"},{"title":"Connection built in","description":"Sails, swims and dinners that rebuild the team.","imageSeed":"fo-connect"},{"title":"1:1 coaching","description":"Private coaching sessions for founders.","imageSeed":"fo-coach"}],"stay":{"property":"Michamvi Peninsula Villa","description":"A private villa on the quiet Michamvi peninsula, with a pool, breakout spaces, reliable connectivity and a chef.","roomTypes":[{"id":"shared","name":"Shared Room","description":"Twin room shared with a colleague.","occupancy":"shared","priceDeltaMinor":0},{"id":"private","name":"Private Room","description":"Your own room in the villa.","occupancy":"private","priceDeltaMinor":55000}],"imageSeeds":["fo-room-1","fo-room-2"]},"inclusions":["7 nights villa accommodation","All meals, prepared by a private chef","Facilitated strategy sessions","Founder 1:1 coaching","Sunset sail and reef swim","Fast connectivity and workspaces","Airport transfers"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Arrive","summary":"Land and unwind.","items":[{"title":"Airport pickup"},{"title":"Team welcome dinner"}]},{"day":2,"title":"Frame","summary":"Set the week''s goals.","items":[{"title":"Opening session"},{"title":"Deep-work block"},{"title":"Sunset swim"}]},{"day":3,"title":"Strategy","summary":"The hard thinking.","items":[{"title":"Strategy workshop"},{"title":"Deep-work block"},{"title":"Group dinner"}]},{"day":4,"title":"Air","summary":"Step back to see clearly.","items":[{"title":"Half-day sail"},{"title":"Reef swim"},{"title":"Informal dinner"}]},{"day":5,"title":"Build","summary":"Turn ideas into plans.","items":[{"title":"Planning session"},{"title":"1:1 coaching"},{"title":"Beach fire"}]},{"day":6,"title":"Commit","summary":"Land the outcomes.","items":[{"title":"Closing workshop"},{"title":"Commitments & roadmap"},{"title":"Farewell dinner"}]},{"day":7,"title":"Depart","summary":"Back, aligned.","items":[{"title":"Breakfast"},{"title":"Airport transfer"}]}],"departures":[{"id":"fs-2026-11","startDate":"2026-11-02","endDate":"2026-11-08","priceFromMinor":245000,"currency":"USD","capacity":14,"spacesRemaining":10,"depositMinor":70000,"balanceDueDays":45,"status":"open"},{"id":"fs-2027-03","startDate":"2027-03-08","endDate":"2027-03-14","priceFromMinor":245000,"currency":"USD","capacity":14,"spacesRemaining":14,"depositMinor":70000,"balanceDueDays":45,"status":"open"}],"featured":false}'::jsonb) on conflict (id) do nothing;
