insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('46572f9f-4f4b-5722-8110-364287ca179c', 'family-castaway-week', 'Family Castaway Week', 'A week of ocean and wonder the whole family will remember.', 'published', '7', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', 'c7742d19-9f19-51ac-9ce0-d3e36c407e23', 'Matemwe, Zanzibar', 'USD', 158000, 20, true, true, '/api/placeholder?seed=pb-family-hero&w=2000&h=1200', '["A week designed so children come home buzzing and parents come home rested. Days are full of gentle adventure — snorkelling in the lagoon, a spice-farm treasure hunt, dhow building and turtle spotting — with a kids'' programme that gives the grown-ups real downtime.","There''s morning yoga for those who want it, a family reef trip everyone can do, and long, easy evenings. It''s a proper holiday that happens to be full of wonder."]'::jsonb, '["You want a family holiday with actual substance.","You''d like the kids busy and amazed, and yourselves rested.","You want time together that everyone remembers."]'::jsonb, '{"slug":"family-castaway-week","name":"Family Castaway Week","strapline":"A week of ocean and wonder the whole family will remember.","duration":7,"destinationSlug":"zanzibar","location":"Matemwe, Zanzibar","categorySlugs":["family","nature"],"hostSlugs":["amina-yusuf","marco-benali"],"verified":true,"currency":"USD","priceFromMinor":158000,"maxGroupSize":20,"heroImageSeed":"family-hero","gallerySeeds":["family-1","family-2","family-3","family-4"],"forYouIf":["You want a family holiday with actual substance.","You''d like the kids busy and amazed, and yourselves rested.","You want time together that everyone remembers."],"story":["A week designed so children come home buzzing and parents come home rested. Days are full of gentle adventure — snorkelling in the lagoon, a spice-farm 