insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('3c8c6fb1-1624-5880-8eb6-af47f8be8d2d', 'wind-and-water', 'Wind & Water', 'Learn to kitesurf on Paje''s world-class flats.', 'published', '7', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', 'c0c8a1c4-cbd8-536e-a1b0-8e29eeaf4e93', 'Paje, Zanzibar', 'USD', 178000, 8, false, false, '/api/placeholder?seed=pb-kite-hero&w=2000&h=1200', '["Paje is one of the world''s great kite spots — steady trade winds, a wide flat lagoon at low tide and warm water. This week gets beginners riding and helps improvers progress fast, with certified instruction every day.","When the wind drops there''s yoga, reef swims and long lazy afternoons. It''s an active week with a laid-back soul."]'::jsonb, '["You want to learn to kitesurf somewhere legendary.","You already ride and want steady wind and flat water.","You like your days windblown and your evenings easy."]'::jsonb, '{"slug":"wind-and-water","name":"Wind & Water","strapline":"Learn to kitesurf on Paje''s world-class flats.","duration":7,"destinationSlug":"zanzibar","location":"Paje, Zanzibar","categorySlugs":["adventure"],"hostSlugs":["marco-benali"],"verified":false,"currency":"USD","priceFromMinor":178000,"maxGroupSize":8,"heroImageSeed":"kite-hero","gallerySeeds":["kite-1","kite-2","kite-3","kite-4"],"forYouIf":["You want to learn to kitesurf somewhere legendary.","You already ride and want steady wind and flat water.","You like your days windblown and your evenings easy."],"story":["Paje is one of the world''s great kite spots — steady trade winds, a wide flat lagoon at low tide and warm water. This week gets beginners riding and helps improvers progress fast, with certified instruction every day.","When the wind drops there''s yoga, reef swims and long lazy afternoons. It''s an active week with a laid-back soul."],"highlights":[{"title":"Daily kite lessons","description":"IKO-certified instruction for every level.","imageSeed":"kt-lesson"},{"title":"Flat-water lagoon","description":"Ideal learning conditions at low tide.","imageSeed":"kt-lagoon"},{"title":"Downwinders","description":"Guided downwind runs for improvers.","imageSeed":"kt-down"},{"title":"Recovery yoga","description":"Wind-down yoga on the low-wind days.","imageSeed":"kt-yoga"}],"stay":{"property":"Paje Kite House","description":"A relaxed beach house on the kite beach, with gear storage, a rinse-off pool and a deck facing the lagoon.","roomTypes":[{"id":"shared","name":"Shared Room","description":"Twin room shared with a fellow rider.","occupancy":"shared","priceDeltaMinor":0},{"id":"private","name":"Private Room","description":"Your own room by the beach.","occupancy":"private","priceDeltaMinor":40000}],"imageSeeds":["kt-room-1","kt-room-2"]},"inclusions":["7 nights accommodation","Breakfast daily","12 hours of kite instruction","All kite equipment","Recovery yoga sessions","Airport transfers"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Arrive","summary":"Feel the wind.","items":[{"title":"Airport pickup"},{"title":"Welcome dinner"},{"title":"Gear check"}]},{"day":2,"title":"Ground school","summary":"The basics.","items":[{"title":"Kite theory"},{"title":"Beach handling"},{"title":"Body-dragging"}]},{"day":3,"title":"First rides","summary":"Up on the board.","items":[{"title":"Water-start practice"},{"title":"Afternoon session"},{"title":"Sunset"}]},{"day":4,"title":"Progress","summary":"Find the flow.","items":[{"title":"Two riding sessions"},{"title":"Recovery yoga on low wind"},{"title":"Dinner"}]},{"day":5,"title":"Ride","summary":"Longer runs.","items":[{"title":"Riding practice"},{"title":"Free afternoon"},{"title":"Beach evening"}]},{"day":6,"title":"Downwind","summary":"Put it together.","items":[{"title":"Guided downwinder"},{"title":"Final session"},{"title":"Group dinner"}]},{"day":7,"title":"Depart","summary":"Wind-happy.","items":[{"title":"Breakfast"},{"title":"Airport transfer"}]}],"departures":[{"id":"ww-2027-01","startDate":"2027-01-11","endDate":"2027-01-17","priceFromMinor":178000,"currency":"USD","capacity":8,"spacesRemaining":6,"depositMinor":50000,"balanceDueDays":45,"status":"open"},{"id":"ww-2027-02","startDate":"2027-02-08","endDate":"2027-02-14","priceFromMinor":178000,"currency":"USD","capacity":8,"spacesRemaining":8,"depositMinor":50000,"balanceDueDays":45,"status":"open"}],"featured":false}'::jsonb) on conflict (id) do nothing;
