insert into experiences (id, slug, name, strapline, status, duration, destination_id, property_id, location_label, currency, price_from_minor, max_group_size, verified, featured, hero_image_url, story, for_you_if, content) values ('7bc0afa5-eb04-5abf-87f4-29da23f0a6eb', 'fourteen-days-beyond-zanzibar', '14 Days Beyond Zanzibar', 'Stone Town → East Coast → Pemba → Beach. The whole archipelago.', 'published', '14', '8248a0e1-98ef-56ea-bb13-6c6487dab2d8', 'b5c0caba-fd02-50f3-9649-c040052175e9', 'Across Zanzibar & Pemba', 'USD', 336000, 12, true, true, '/api/placeholder?seed=pb-beyond-hero&w=2000&h=1200', '["Not every trip needs to be a retreat. This is a curated fortnight across the whole archipelago — the history of Stone Town, the kite beaches of the east, the wild reefs of Pemba and days of pure beach at the end.","Accommodation, every transfer and a handful of standout experiences are arranged for you. You bring yourself; we handle the rest. It''s the Paradise Beyond holiday, complete."]'::jsonb, '["You want to see the whole archipelago, beautifully arranged.","You''d rather have it all handled than plan it yourself.","You want a holiday, not a retreat — with substance built in."]'::jsonb, '{"slug":"fourteen-days-beyond-zanzibar","name":"14 Days Beyond Zanzibar","strapline":"Stone Town → East Coast → Pemba → Beach. The whole archipelago.","duration":14,"destinationSlug":"zanzibar","location":"Across Zanzibar & Pemba","categorySlugs":["paradise-holidays"],"hostSlugs":["fatma-said","james-okoth"],"verified":true,"currency":"USD","priceFromMinor":336000,"maxGroupSize":12,"heroImageSeed":"beyond-hero","gallerySeeds":["beyond-1","beyond-2","beyond-3","beyond-4"],"forYouIf":["You want to see the whole archipelago, beautifully arranged.","You''d rather have it all handled than plan it yourself.","You want a holiday, not a retreat — with substance built in."],"story":["Not every trip needs to be a retreat. This is a curated fortnight across the whole archipelago — the history of Stone Town, the kite beaches of the east, the wild reefs of Pemba and days of pure beach at the end.","Accommodation, every transfer and a handful of standout experiences are arranged for you. You bring yourself; we handle the rest. It''s the Paradise Beyond holiday, complete."],"highlights":[{"title":"Stone Town","description":"Guided history, food and the great market.","imageSeed":"by-stone"},{"title":"East coast","description":"Kite beaches, sandbanks and lagoon days.","imageSeed":"by-east"},{"title":"Pemba crossing","description":"The wild, green sister island and its reefs.","imageSeed":"by-pemba"},{"title":"Beach finish","description":"Days of nothing but sea and sand to close.","imageSeed":"by-beach"}],"stay":{"property":"Four hand-picked stays across the islands","description":"A heritage house in Stone Town, a lagoon lodge on the east coast, an eco lodge on Pemba and a beach hotel to finish — each chosen for its character.","roomTypes":[{"id":"shared","name":"Shared Twin","description":"Twin rooms shared throughout the journey.","occupancy":"shared","priceDeltaMinor":0},{"id":"private","name":"Private Room","description":"Private rooms at every stay.","occupancy":"private","priceDeltaMinor":88000}],"imageSeeds":["by-room-1","by-room-2","by-room-3"]},"inclusions":["13 nights across four hand-picked stays","Breakfast daily, several dinners","All inter-island transfers and flights within Tanzania","Stone Town guided day","East-coast lagoon experiences","Pemba reef trip","Airport transfers"],"exclusions":["International flights","Travel insurance","Visa fees","Personal purchases","Unscheduled activities & excursions"],"itinerary":[{"day":1,"title":"Stone Town","summary":"Arrive into history.","items":[{"title":"Airport pickup"},{"title":"Old-town welcome walk"},{"title":"Rooftop dinner"}]},{"day":2,"title":"Stone Town","summary":"The city in full.","items":[{"title":"Guided history tour"},{"title":"Darajani market"},{"title":"Forodhani night market"}]},{"day":3,"title":"Spice","summary":"Into the interior.","items":[{"title":"Spice-farm day"},{"title":"Farm lunch"},{"title":"Return to town"}]},{"day":4,"title":"East coast","summary":"To the lagoon.","items":[{"title":"Transfer east"},{"title":"Beach afternoon"},{"title":"Seafood dinner"}]},{"day":5,"title":"Lagoon","summary":"Turquoise days.","items":[{"title":"Sandbank trip"},{"title":"Free afternoon"},{"title":"Sunset"}]},{"day":6,"title":"East coast","summary":"Reef and rest.","items":[{"title":"Snorkelling trip"},{"title":"Beach time"},{"title":"Dinner"}]},{"day":7,"title":"Jozani","summary":"Forest and monkeys.","items":[{"title":"Jozani forest walk"},{"title":"Return"},{"title":"Leisure evening"}]},{"day":8,"title":"To Pemba","summary":"The wild island.","items":[{"title":"Flight to Pemba"},{"title":"Eco-lodge settle-in"},{"title":"Dinner"}]},{"day":9,"title":"Pemba","summary":"Green and quiet.","items":[{"title":"Island tour"},{"title":"Cove swim"},{"title":"Sunset"}]},{"day":10,"title":"Pemba reef","summary":"Under the water.","items":[{"title":"Reef snorkel / dive"},{"title":"Beach afternoon"},{"title":"Dinner"}]},{"day":11,"title":"To the beach","summary":"The final stretch.","items":[{"title":"Flight & transfer"},{"title":"Beach hotel check-in"},{"title":"Dinner"}]},{"day":12,"title":"Beach","summary":"Do nothing beautifully.","items":[{"title":"Free beach day"},{"title":"Optional spa"},{"title":"Sunset dinner"}]},{"day":13,"title":"Beach","summary":"One more perfect day.","items":[{"title":"Free day"},{"title":"Dhow sunset sail"},{"title":"Farewell dinner"}]},{"day":14,"title":"Depart","summary":"The whole island seen.","items":[{"title":"Breakfast"},{"title":"Airport transfer"}]}],"departures":[{"id":"bz-2026-11","startDate":"2026-11-07","endDate":"2026-11-20","priceFromMinor":336000,"currency":"USD","capacity":12,"spacesRemaining":8,"depositMinor":100000,"balanceDueDays":45,"status":"open"},{"id":"bz-2027-01","startDate":"2027-01-23","endDate":"2027-